/* CSA5111 Question 26: independent executable */
#include "common/crypto_common.h"
static void q26(void){char ns[256],es[256],ds[256];readstr("RSA modulus n (decimal): ",ns,sizeof ns);readstr("Public exponent e (decimal): ",es,sizeof es);readstr("Leaked private exponent d (decimal): ",ds,sizeof ds);BIGNUM*n=NULL,*e=NULL,*d=NULL,*k=BN_new(),*r=BN_new(),*g=BN_new(),*y=BN_new(),*x=BN_new(),*nm1=BN_new(),*p=BN_new(),*q=BN_new(),*two=BN_new();BN_CTX*ctx=BN_CTX_new();BN_dec2bn(&n,ns);BN_dec2bn(&e,es);BN_dec2bn(&d,ds);BN_mul(k,e,d,ctx);BN_sub_word(k,1);BN_copy(r,k);int t=0;while(!BN_is_bit_set(r,0)){BN_rshift1(r,r);t++;}BN_copy(nm1,n);BN_sub_word(nm1,1);BN_set_word(two,2);int found=0;for(int attempt=0;attempt<80&&!found;attempt++){if(!BN_rand_range(g,nm1))continue;if(BN_cmp(g,two)<0)BN_add(g,g,two);BN_mod_exp(y,g,r,n,ctx);if(BN_is_one(y)||BN_cmp(y,nm1)==0)continue;for(int j=0;j<t;j++){BN_mod_sqr(x,y,n,ctx);if(BN_is_one(x)){BN_copy(p,y);BN_sub_word(p,1);BN_gcd(p,p,n,ctx);if(!BN_is_one(p)&&BN_cmp(p,n)!=0){BN_div(q,NULL,n,p,ctx);found=1;}break;}if(BN_cmp(x,nm1)==0)break;BN_copy(y,x);}}if(found){printf("Recovered p=");BN_print_fp(stdout,p);printf(" q=");BN_print_fp(stdout,q);puts("");puts("The leaked (e,d,n) relation can factor n; changing e and d while reusing n is unsafe.");}else puts("Factor recovery attempt did not find p,q (retry with valid RSA keys).");BN_free(n);BN_free(e);BN_free(d);BN_free(k);BN_free(r);BN_free(g);BN_free(y);BN_free(x);BN_free(nm1);BN_free(p);BN_free(q);BN_free(two);BN_CTX_free(ctx);}
int main(void){ OSSL_PROVIDER_load(NULL,"default"); OSSL_PROVIDER_load(NULL,"legacy"); q26(); return 0; }
